import{_ as n,a0 as o,w as d,s as r,ao as l,I as i,x as s,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"详解在 Ubuntu 从外部存储库安装软件包 | LCTT x X-CMD","titleTemplate":false,"description":"详解在 Ubuntu 从外部存储库安装软件包 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"详解在 Ubuntu 从外部存储库安装软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"详解在 Ubuntu 从外部存储库安装软件包 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210805 Installing Packages From External Repositories in Ubuntu -Explained","title":"详解在 Ubuntu 从外部存储库安装软件包","tag":"202211","desc":""},"relativePath":"202211/20210805 Installing Packages From External Repositories in Ubuntu -Explained.md","filePath":"[post].md"}'),u={name:"202211/20210805 Installing Packages From External Repositories in Ubuntu -Explained.md"};function g(b,t,h,k,m,f){const e=o("Link");return d(),r("div",null,[t[50]||(t[50]=l('<h1 id="详解在-ubuntu-从外部存储库安装软件包" tabindex="-1">详解在 Ubuntu 从外部存储库安装软件包 <a class="header-anchor" href="#详解在-ubuntu-从外部存储库安装软件包" aria-label="Permalink to “详解在 Ubuntu 从外部存储库安装软件包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/29/154339id0xb2exw0c8y222.jpg" alt=""></p><p>你大概知道怎么在 Ubuntu 中使用 <code>apt</code> 命令安装软件包。那些软件包都是来自 Ubuntu 的官方存储库。</p><p>那第三方或者外部存储库呢？不，我这里并不是要讲 PPA。</p><p>早晚你会碰到那种至少四行的安装说明：你需要安装名为 <code>apt-transport-https</code> 的包、操作一下 GPG 和 <ruby>源列表<rt>source list</rt></ruby> 之后，你才能正常安装软件包。</p>',5)),i("p",null,[t[1]||(t[1]=s("没有什么印象的话，那我分享一个 ",-1)),p(e,{href:"https://itsfoss.com/install-yarn-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[s("在 Ubuntu 上安装最新版本的 Yarn",-1)])]),_:1}),t[2]||(t[2]=s(" 的例子：",-1))]),t[51]||(t[51]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install apt-transport-https curl</span></span>
<span class="line"><span>curl -sS https://dl.yarnpkg.com/debian/pubkey.gpg | sudo apt-key add -</span></span>
<span class="line"><span>sudo sh -c &#39;echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; &gt;&gt; /etc/apt/sources.list.d/yarn.list&#39;</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install yarn</span></span></code></pre></div><p>当你需要直接从开发者那里安装编程工具的时候，大概率会碰到这种安装方式。</p><p>许多人只是按照说明进行操作，并不会去思考其中的原理。这也没什么不对，但了解该过程实际上可以提升你在这方面的知识，而且有助于之后排除故障。</p><p>我来解释一下这些代码背后的逻辑。</p><h3 id="理解从外部存储库安装的过程" tabindex="-1">理解从外部存储库安装的过程 <a class="header-anchor" href="#理解从外部存储库安装的过程" aria-label="Permalink to “理解从外部存储库安装的过程”">​</a></h3><p>在你继续往下阅读之前，我强烈建议你先看看下面这两篇文章，方便理解后续的概念：</p>`,6)),i("ul",null,[i("li",null,[p(e,{href:"https://itsfoss.com/ubuntu-repositories/"},{default:a(()=>[...t[3]||(t[3]=[s("什么是 Ubuntu 中的存储库",-1)])]),_:1})]),i("li",null,[p(e,{href:"https://itsfoss.com/ppa-guide/#comments"},{default:a(()=>[...t[4]||(t[4]=[s("什么是 Ubuntu 中 PPA",-1)])]),_:1})])]),i("p",null,[t[6]||(t[6]=s("为了让你有点印象，这里有一张软件包存储库和 ",-1)),p(e,{href:"https://itsfoss.com/package-manager/"},{default:a(()=>[...t[5]||(t[5]=[s("Linux 中的包管理器",-1)])]),_:1}),t[7]||(t[7]=s(" 的图片。",-1))]),t[52]||(t[52]=l('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/linux-package-manager-explanation.png?resize=800%2C450&amp;ssl=1" alt="Illustration of repository and package manager"></p><p>整件事情其实就是在系统中添加一个新的外部存储库。这样，你就可以从这个新存储库下载并安装可用的软件包。如果这个存储库提供了包版本的更新，你可以在更新系统的同时更新这些软件包（<code>apt update &amp;&amp; apt upgrade</code>）。</p><p>那么，这是什么工作原理呢？让我们一条一条地过一遍。</p><h4 id="第-1-部分-为-apt-获取-https-支持" tabindex="-1">第 1 部分：为 apt 获取 HTTPS 支持 <a class="header-anchor" href="#第-1-部分-为-apt-获取-https-支持" aria-label="Permalink to “第 1 部分：为 apt 获取 HTTPS 支持”">​</a></h4><p>第一行是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install apt-transport-https curl</span></span></code></pre></div>',6)),i("p",null,[t[9]||(t[9]=i("code",null,"curl",-1)),t[10]||(t[10]=s(" 是一个 ",-1)),p(e,{href:"https://itsfoss.com/download-files-from-linux-terminal/"},{default:a(()=>[...t[8]||(t[8]=[s("Linux 终端下载文件的工具",-1)])]),_:1}),t[11]||(t[11]=s("。这里主要的部分是安装 ",-1)),t[12]||(t[12]=i("code",null,"apt-transport-https",-1)),t[13]||(t[13]=s("，但事实上已经不需要了。",-1))]),t[53]||(t[53]=l('<p>明白了吗？这个 <code>apt-transport-https</code> 包让你的系统通过 HTTPS 协议安全访问存储库。按照设计，Ubuntu 的存储库使用 http 而不是 https 协议。</p><p>看看下面的截图。 https 这张图是我已经添加到系统中的外部存储库。Ubuntu 的存储库和 PPA 使用 http 协议。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/apt-update-http-https.png?resize=800%2C527&amp;ssl=1" alt=""></p><p>在旧版本的 <code>apt</code> 包管理器中，不支持 https 协议。<code>apt-transport-https</code> 包为 <code>apt</code> 添加了 https 支持。要新增一个使用 https 的存储库，首先就得先安装此包。</p><p>我之前不是说不需要安装这个包了吗？是的，因为较新版本的 <code>apt</code>（高于 1.5）已经支持 https，所以你不需要再安装 <code>apt-transport-https</code>。</p><p>但是你依然看到我在说明中提到了这个包。这更多是出于遗留原因，而且可能还有很旧的发行版在使用旧版本的 <code>apt</code> 包。</p><p>现在，你可能想知道既然 https 是安全协议，那为什么 Ubuntu 的存储库还要使用 http 而不是 https。这难道没有安全风险吗？接着往下看你就知道答案了。</p><h4 id="第-2-部分-添加远程存储库的-gpg-密钥" tabindex="-1">第 2 部分：添加远程存储库的 GPG 密钥 <a class="header-anchor" href="#第-2-部分-添加远程存储库的-gpg-密钥" aria-label="Permalink to “第 2 部分：添加远程存储库的 GPG 密钥”">​</a></h4><p>Linux 存储库内置了基于 GPG 密钥的安全机制。每个存储库都将其 GPG 公钥添加到你的系统信任密钥中。来自存储库的包由这个 GPG 密钥“<ruby>签名<rt>signed</rt></ruby>”，并且通过这份存储的公钥，系统能够验证软件包正是来自这个存储库。</p>',9)),i("p",null,[t[15]||(t[15]=s("如果 ",-1)),p(e,{href:"https://itsfoss.com/solve-gpg-error-signatures-verified-ubuntu/"},{default:a(()=>[...t[14]||(t[14]=[s("密钥之间不匹配，你的系统会发出提醒",-1)])]),_:1}),t[16]||(t[16]=s("，而不会继续从该存储库安装或者更新软件包。",-1))]),t[54]||(t[54]=l('<p>到目前为止，一切都很顺利。下一步是将外部存储库的 GPG 公钥添加到你的 Linux 系统，以便它能接收来自该存储库的软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -sS https://dl.yarnpkg.com/debian/pubkey.gpg | sudo apt-key add -</span></span></code></pre></div><p>在上面的命令中，你使用 <code>curl</code> 从指定的 URL 下载 GPG 密钥。选项 <code>-sS</code> 能够让你不看多余的输出（静默模式），但会显示错误（如果有的话）。最后一个 <code>-</code> 告诉 <code>apt-key</code> 使用<ruby>标准输入<rt>stdin</rt></ruby>而不是文件（在本例中是 <code>curl</code> 命令的输出）。</p><p><code>apt-key add</code> 命令已经将下载的密钥添加到系统中。</p><p>你可以通过 <code>apt-key list</code> 命令查看系统中各种存储库添加的 GPG 密钥。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/07/list-apt-key-gpg-ubuntu.png?resize=800%2C547&amp;ssl=1" alt="List GPG keys"></p><p>这是将 GPG 密钥添加到系统的一种方法。你会看到一些其它的命令，看起来略有不同，但效果一样，都是将存储库的公钥添加到你的系统里面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys E298A3A825C0D65DFD57CBB651716619E084DAB9</span></span></code></pre></div><p>你会注意到 <code>apt-key</code> 已被弃用的警告。在 Ubuntu 22.04 之前，你还可以使用 <code>apt-key</code> 命令，但它最终会被删除。现在不需要杞人忧天。</p><h4 id="第-3-部分-将外部存储库添加到源列表" tabindex="-1">第 3 部分：将外部存储库添加到源列表 <a class="header-anchor" href="#第-3-部分-将外部存储库添加到源列表" aria-label="Permalink to “第 3 部分：将外部存储库添加到源列表”">​</a></h4><p>下个命令是在系统的源列表中添加一个新条目。这样，你的系统就会知道它得检查该存储库中的包和更新。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo sh -c &#39;echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; &gt;&gt; /etc/apt/sources.list.d/yarn.list&#39;</span></span></code></pre></div><p>有一个文件 <code>/etc/apt/sources.list</code> 包含 Ubuntu 存储库的详细信息。最好不要随便动这个文件。所有新增的存储库都应放在 <code>/etc/apt/sources.list.d</code> 目录中相应的文件里（约定以 <code>.list</code> 结尾）。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/sources-list-ubuntu.png?resize=800%2C313&amp;ssl=1" alt="External repository should have their own sources list file in the /etc/apt/sources.list.d directory"></p><p>这使得包管理变得更容易。如果你要从系统中删除一个存储库，只需删除相应的源文件即可。无需修改主 <code>sources.list</code> 文件。</p><p>让我们再仔细地看一下这行命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo sh -c &#39;echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; &gt;&gt; /etc/apt/sources.list.d/yarn.list&#39;</span></span></code></pre></div>',17)),i("p",null,[t[18]||(t[18]=s("使用 ",-1)),t[19]||(t[19]=i("code",null,"sh",-1)),t[20]||(t[20]=s(" 可以在一个新的 shell 进程中运行命令，而不是 ",-1)),p(e,{href:"https://linuxhandbook.com/subshell/"},{default:a(()=>[...t[17]||(t[17]=[s("子 shel​​l",-1)])]),_:1}),t[21]||(t[21]=s("。 ",-1)),t[22]||(t[22]=i("code",null,"-c",-1)),t[23]||(t[23]=s(" 选项告诉 ",-1)),t[24]||(t[24]=i("code",null,"sh",-1)),t[25]||(t[25]=s(" 命令从参数而不是标准输入读取命令。然后它运行 ",-1)),t[26]||(t[26]=i("code",null,"echo",-1)),t[27]||(t[27]=s(" 命令，也就是把 ",-1)),t[28]||(t[28]=i("code",null,"deb https://dl.yarnpkg.com/debian/ stable main",-1)),t[29]||(t[29]=s(" 这一行添加到 ",-1)),t[30]||(t[30]=i("code",null,"/etc/apt/sources.list.d/yarn.list",-1)),t[31]||(t[31]=s(" 文件（会创建该文件）。",-1))]),t[55]||(t[55]=l('<p>现在，你可以通过各种方法在指定目录中创建 <code>.list</code> 文件并在其中添加包含存储库详细信息的数据行。你也可以像这样使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;deb https://dl.yarnpkg.com/debian/ stable main&quot; | sudo tee /etc/apt/sources.list.d/yarn.list</span></span></code></pre></div><p>明白了吧？</p><h4 id="第-4-部分-从新添加的存储库安装应用程序" tabindex="-1">第 4 部分：从新添加的存储库安装应用程序 <a class="header-anchor" href="#第-4-部分-从新添加的存储库安装应用程序" aria-label="Permalink to “第 4 部分：从新添加的存储库安装应用程序”">​</a></h4><p>到目前为止，你已经将存储库的 GPG 密钥和存储库的 URL 添加到系统中。</p><p>但是系统仍然不晓得这个新存储库中有哪些可用的包。这就是为什么你需要先使用下面这个命令更新包元数据的本地缓存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>这时你的系统就已经知道新增存储库中可用软件包的信息，现在可以试试安装软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install yarn</span></span></code></pre></div>',9)),i("p",null,[t[33]||(t[33]=s("为了节省时间，你可以在 ",-1)),p(e,{href:"https://itsfoss.com/run-multiple-commands-linux/"},{default:a(()=>[...t[32]||(t[32]=[s("同一行挨着运行这两个命令",-1)])]),_:1}),t[34]||(t[34]=s("e。",-1))]),t[56]||(t[56]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install yarn</span></span></code></pre></div><p><code>&amp;&amp;</code> 可以确保第二个命令只会在前一个命令没有任何报错的前提下运行。</p><p>整个流程就是这样。</p><h4 id="有没有豁然开朗呢-还是一脸懵逼" tabindex="-1">有没有豁然开朗呢，还是一脸懵逼？ <a class="header-anchor" href="#有没有豁然开朗呢-还是一脸懵逼" aria-label="Permalink to “有没有豁然开朗呢，还是一脸懵逼？”">​</a></h4><p>我已经解释了在 Ubuntu 中使用外部存储库背后的逻辑。希望你现在能更好地理解它，当然可能还有很多细节会让你困惑。</p><p>如果你还不清楚或者还有其他问题，可以联系我。如果你发现了技术上的纰漏，记得在评论区告诉我。</p><hr>',7)),i("p",null,[t[36]||(t[36]=s("via: ",-1)),p(e,{href:"https://itsfoss.com/adding-external-repositories-ubuntu/"},{default:a(()=>[...t[35]||(t[35]=[s("https://itsfoss.com/adding-external-repositories-ubuntu/",-1)])]),_:1})]),i("p",null,[t[41]||(t[41]=s("作者：",-1)),p(e,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...t[37]||(t[37]=[s("Abhishek Prakash",-1)])]),_:1}),t[42]||(t[42]=s(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[38]||(t[38]=[s("lujun9972",-1)])]),_:1}),t[43]||(t[43]=s(" 译者：",-1)),p(e,{href:"https://github.com/nophDog"},{default:a(()=>[...t[39]||(t[39]=[s("nophDog",-1)])]),_:1}),t[44]||(t[44]=s(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[40]||(t[40]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[47]||(t[47]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[45]||(t[45]=[s("LCTT",-1)])]),_:1}),t[48]||(t[48]=s(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:a(()=>[...t[46]||(t[46]=[s("Linux中国",-1)])]),_:1}),t[49]||(t[49]=s(" 荣誉推出",-1))])])}const x=n(u,[["render",g]]);export{C as __pageData,x as default};
